package me.minis.ledger;
import java.util.*;
public class Card368Test{
 static int checks;static long now,time;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 static WechatCardStructure.Node node(int id,int parent,String role,int top,int bottom,String text,String desc){WechatCardStructure.Node n=new WechatCardStructure.Node();n.id=id;n.parent=parent;n.viewId="com.tencent.mm:id/"+role;n.left=0;n.right=400;n.top=top;n.bottom=bottom;n.visible=true;n.text=text;n.desc=desc;n.clazz=role.equals("c6b")?"RecyclerView":"TextView";return n;}
 static List<WechatCardStructure.Node> fixture(String clock,boolean desc,boolean sibling){List<WechatCardStructure.Node> a=new ArrayList<>();a.add(node(0,-1,"c6b",0,900,"",""));a.add(node(1,0,"c3t",sibling?100:20,500,"",""));a.add(node(2,sibling?0:1,"c8t",20,80,desc?"":clock,desc?clock:""));a.add(node(3,1,"c44",100,500,"",""));a.add(node(4,3,"mnx",110,160,"合成餐饮店",""));a.add(node(5,3,"body",170,220,"使用建设银行储蓄卡(1234)支付",""));a.add(node(6,3,"money",230,300,"¥12.00",""));a.add(node(7,3,"footer",310,380,"账单详情",""));return a;}
 static List<WechatReceiptParser.Receipt> parse(List<WechatCardStructure.Node>a){return WechatCardText.parse("com.tencent.mm",Arrays.asList("微信支付","我的账单","支付服务","优惠"),a,false,now);}
 public static void main(String[]args){TimeZone.setDefault(TimeZone.getTimeZone("Asia/Shanghai"));Calendar c=Calendar.getInstance();c.clear();c.set(2026,9,30,12,39);now=c.getTimeInMillis();c.set(Calendar.HOUR_OF_DAY,11);c.set(Calendar.MINUTE,26);time=c.getTimeInMillis();
 if(args.length>0){List<WechatReceiptParser.Receipt> rs=parse(fixture("上午11:26",true,false));ok(rs.size()==1&&rs.get(0).time==0,"old parser loses description timestamp");System.out.println("REPRODUCED old description clock lost => r.time=0 => observation-time fallback");return;}
 for(String clock:new String[]{"上午11:26","上午\u00a011:26","上午11:26\u200b","2026-10-30 11:26:00"})for(boolean desc:new boolean[]{false,true})for(boolean sibling:new boolean[]{false,true}){List<WechatReceiptParser.Receipt> rs=parse(fixture(clock,desc,sibling));ok(rs.size()==1,"one isolated card "+clock);ok(rs.get(0).time==time,"correct clock "+clock+desc+sibling);ok(!rs.get(0).result.confirmed,"history still review if no prior");ok(rs.get(0).key.contains(""+time),"stable receipt key");}
 List<WechatCardStructure.Node> a=fixture("上午11:26",true,true);a.get(2).text="上一张卡片";ok(parse(a).get(0).time==0,"never borrow prior payment clock");a=fixture("上午11:26",true,false);a.get(2).text="中午12:07";ok(parse(a).get(0).time==0,"conflicting timestamp rejected");
 a=fixture("上午11:26",true,true);a.get(2).top=-30;ok(parse(a).get(0).time==0,"offscreen clock not borrowed");
 List<String> feed=Arrays.asList("微信支付","我的账单","支付服务","上午11:26","合成餐饮店","使用建设银行储蓄卡(1234)支付","¥12.00","账单详情","中午12:07","合成快递店","使用建设银行储蓄卡(1234)支付","¥15.00","账单详情");List<WechatReceiptParser.Receipt> rs=WechatReceiptParser.parseAll("com.tencent.mm",feed,now);ok(rs.size()==2,"two cards isolated");ok(rs.get(0).time==time&&rs.get(1).time==time+41*60000,"both clocks correct not 12:39");
 for(int i=0;i<60;i++){rs=WechatReceiptParser.parseAll("com.tencent.mm",feed,now+i*1000);ok(rs.get(0).time==time,"reopen does not rewrite time");}
 ok(TransactionTime.clock("2026-02-30 11:26",now)==0,"invalid date");ok(TransactionTime.clock("下午25:00",now)==0,"invalid hour");ok(TransactionTime.labelled("支付时间：2026-10-30 11:26\n交易时间：2026-10-30 12:07",now)==0,"conflicting labelled times");
 System.out.println("PASS "+checks+" isolated card/time368 Java assertions; synthetic nodes, not live WeChat tree");}
}
